test('jitter: true applies full jitter to delay', async t => {
	const retryCount = 3;
	let requestCount = 0;
	const delays: number[] = [];
	let lastTime = Date.now();

	const server = await createHttpTestServer();
	server.get('/', (_request, response) => {
		const now = Date.now();
		if (requestCount > 0) {
