	// Full jitter should produce delays between 0 and the computed delay
	// Add 20% tolerance for system overhead
	t.true(delays[0] >= 0 && delays[0] <= 360);
	t.true(delays[1] >= 0 && delays[1] <= 720);
	t.true(delays[2] >= 0 && delays[2] <= 1440);

